import Foundation

/// `Settings` as a JSON object, for the settings helper process. Every field is written; decoding
/// needs every field, so the two processes can never silently disagree.
public enum SettingsCoding {
    public static func encode(_ s: Settings) -> [String: Any] {
        [
            "maxItems": s.maxItems, "maxTextBytes": s.maxTextBytes, "maxImageBytes": s.maxImageBytes,
            "maxImageTotalBytes": s.maxImageTotalBytes, "detectSensitive": s.detectSensitive,
            "sensitiveTtlMs": s.sensitiveTtlMs, "keepAutoGenerated": s.keepAutoGenerated,
            "ignoredApps": s.ignoredApps, "allowListMode": s.allowListMode, "allowedApps": s.allowedApps,
            "ignoredTypes": s.ignoredTypes, "ignorePatterns": s.ignorePatterns, "recordText": s.recordText,
            "recordImages": s.recordImages, "recordFiles": s.recordFiles,
            "searchMode": name(s.searchMode, searchModes), "sort": name(s.sort, sortOrders),
            "pinPosition": name(s.pinPosition, pinPositions), "pasteAutomatically": s.pasteAutomatically,
            "pastePlainByDefault": s.pastePlainByDefault, "popupPosition": name(s.popupPosition, popupPositions),
            "historyShortcut": s.historyShortcut, "captureShortcut": s.captureShortcut,
            "pollIntervalMs": s.pollIntervalMs, "showSpecialChars": s.showSpecialChars,
            "showMenuIcon": s.showMenuIcon, "menuIcon": name(s.menuIcon, menuIcons),
            "showRecentInMenuBar": s.showRecentInMenuBar, "clearOnQuit": s.clearOnQuit,
            "visibleItems": s.visibleItems, "imagePreviewHeight": s.imagePreviewHeight,
            "language": name(s.language, languages),
        ]
    }

    /// The settings in `object`, or `nil` when any field is missing or has the wrong type.
    public static func decode(_ object: [String: Any]) -> Settings? {
        let reader = Reader(object)
        guard let settings = reader.settings(), reader.ok else { return nil }
        return settings
    }

    static let searchModes: [(SearchMode, String)] = [(.fuzzy, "fuzzy"), (.exact, "exact"), (.regex, "regex"), (.mixed, "mixed")]
    static let sortOrders: [(SortOrder, String)] = [(.lastUsed, "lastUsed"), (.firstCopied, "firstCopied"), (.copyCount, "copyCount")]
    static let pinPositions: [(PinPosition, String)] = [(.top, "top"), (.bottom, "bottom")]
    static let popupPositions: [(PopupPosition, String)] = [
        (.cursor, "cursor"), (.menuIcon, "menuIcon"), (.screenCenter, "screenCenter"), (.lastPosition, "lastPosition"),
    ]
    static let menuIcons: [(MenuIcon, String)] = [(.clipboard, "clipboard"), (.paperclip, "paperclip"), (.scissors, "scissors"), (.stack, "stack")]
    static let languages: [(Language, String)] = [(.system, "system"), (.simplifiedChinese, "simplifiedChinese"), (.english, "english")]

    static func name<T: Equatable>(_ value: T, _ table: [(T, String)]) -> String {
        table.first { $0.0 == value }?.1 ?? ""
    }

    /// Reads typed fields and remembers whether any was missing.
    private final class Reader {
        let object: [String: Any]
        var ok = true

        init(_ object: [String: Any]) { self.object = object }

        func number(_ key: String) -> NSNumber? {
            guard let value = object[key] as? NSNumber else { ok = false; return nil }
            return value
        }

        func u32(_ key: String) -> UInt32 { number(key)?.uint32Value ?? 0 }
        func u64(_ key: String) -> UInt64 { number(key)?.uint64Value ?? 0 }

        func bool(_ key: String) -> Bool {
            guard let value = object[key] as? Bool else { ok = false; return false }
            return value
        }

        func string(_ key: String) -> String {
            guard let value = object[key] as? String else { ok = false; return "" }
            return value
        }

        func strings(_ key: String) -> [String] {
            guard let value = object[key] as? [String] else { ok = false; return [] }
            return value
        }

        func choice<T>(_ key: String, _ table: [(T, String)]) -> T? {
            let text = string(key)
            guard let value = table.first(where: { $0.1 == text })?.0 else { ok = false; return nil }
            return value
        }

        func settings() -> Settings? {
            guard let searchMode = choice("searchMode", SettingsCoding.searchModes),
                  let sort = choice("sort", SettingsCoding.sortOrders),
                  let pinPosition = choice("pinPosition", SettingsCoding.pinPositions),
                  let popupPosition = choice("popupPosition", SettingsCoding.popupPositions),
                  let menuIcon = choice("menuIcon", SettingsCoding.menuIcons),
                  let language = choice("language", SettingsCoding.languages)
            else { return nil }
            return Settings(
                maxItems: u32("maxItems"), maxTextBytes: u32("maxTextBytes"), maxImageBytes: u32("maxImageBytes"),
                maxImageTotalBytes: u64("maxImageTotalBytes"), detectSensitive: bool("detectSensitive"),
                sensitiveTtlMs: u64("sensitiveTtlMs"), keepAutoGenerated: bool("keepAutoGenerated"),
                ignoredApps: strings("ignoredApps"), allowListMode: bool("allowListMode"),
                allowedApps: strings("allowedApps"), ignoredTypes: strings("ignoredTypes"),
                ignorePatterns: strings("ignorePatterns"), recordText: bool("recordText"),
                recordImages: bool("recordImages"), recordFiles: bool("recordFiles"), searchMode: searchMode,
                sort: sort, pinPosition: pinPosition, pasteAutomatically: bool("pasteAutomatically"),
                pastePlainByDefault: bool("pastePlainByDefault"), popupPosition: popupPosition,
                historyShortcut: string("historyShortcut"), captureShortcut: string("captureShortcut"),
                pollIntervalMs: u32("pollIntervalMs"), showSpecialChars: bool("showSpecialChars"),
                showMenuIcon: bool("showMenuIcon"), menuIcon: menuIcon,
                showRecentInMenuBar: bool("showRecentInMenuBar"), clearOnQuit: bool("clearOnQuit"),
                visibleItems: u32("visibleItems"), imagePreviewHeight: u32("imagePreviewHeight"), language: language
            )
        }
    }
}
